def geo_gearys_c(y=None, W=None, transform=None):
    """Geary's C spatial autocorrelation with normal and randomization inference. Geary's contiguity ratio C of a variable with a given spatial weights matrix, its variance under normality and randomization, and the z-scores (C < 1 positive, C > 1 negative autocorrelation).
    Formula: C = \\frac{(n-1)\\sum_i\\sum_j w_{ij}(y_i - y_j)^2}{2S_0\\sum_i (y_i - \\bar y)^2},\\quad V_N[C] = \\frac{(2S_1 + S_2)(n-1) - 4S_0^2}{2(n+1)S_0^2}
    Inputs:
        y: values at the n locations
        W: spatial weights matrix (n x n, zero diagonal, row i lists the weights of i's neighbours)
        transform: row-standardize the weights (row) or use them as given (none)
    Outputs: C (Geary's C), VC_norm (variance under normality), z_norm (z-score under normality), VC_rand (variance under randomization), z_rand (z-score under randomization)
    See also: help("geo_gearys_c")
    """
    given = {k: v for k, v in dict(y=y, W=W, transform=transform).items() if v is not None}
    return _P.solve("geo_gearys_c", **given)

def geo_geodesic_destination(lat1=None, lon1=None, azimuth=None, distance=None, ellipsoid=None):
    """Geodesic destination point on the ellipsoid (direct problem). The point reached by travelling a given distance along a geodesic from a start point at a given initial azimuth on the WGS84 or GRS80 ellipsoid, and the azimuth of the geodesic on arrival.
    Formula: \\frac{s}{b} = \\int_{\\sigma_1}^{\\sigma_2}\\sqrt{1 + k^2\\sin^2\\sigma}\\,d\\sigma,\\quad \\lambda_{12} = \\omega_{12} - f\\sin\\alpha_0\\int_{\\sigma_1}^{\\sigma_2}\\frac{2-f}{1 + (1-f)\\sqrt{1+k^2\\sin^2\\sigma}}\\,d\\sigma
    Inputs:
        lat1: latitude of the start point (decimal degrees)
        lon1: longitude of the start point (decimal degrees)
        azimuth: initial azimuth, clockwise from north (decimal degrees)
        distance: geodesic distance travelled
        ellipsoid: reference ellipsoid
    Outputs: lat2 (latitude of the destination (degrees)), lon2 (longitude of the destination (degrees)), azimuth2 (forward azimuth at the destination (degrees clockwise from north))
    See also: help("geo_geodesic_destination")
    """
    given = {k: v for k, v in dict(lat1=lat1, lon1=lon1, azimuth=azimuth, distance=distance, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_geodesic_destination", **given)

def geo_geodesic_midpoint(lat1=None, lon1=None, lat2=None, lon2=None, ellipsoid=None):
    """Midpoint of a geodesic on the ellipsoid. The point halfway along the shortest path (geodesic) between two points on the WGS84 or GRS80 ellipsoid, with the geodesic length.
    Formula: P_{mid} = \\mathrm{direct}\\left(P_1,\\ \\alpha_1,\\ s_{12}/2\\right)
    Inputs:
        lat1: latitude of the first point (decimal degrees)
        lon1: longitude of the first point (decimal degrees)
        lat2: latitude of the second point (decimal degrees)
        lon2: longitude of the second point (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: lat_mid (latitude of the midpoint (degrees)), lon_mid (longitude of the midpoint (degrees)), distance (length of the geodesic between the two points)
    See also: help("geo_geodesic_midpoint")
    """
    given = {k: v for k, v in dict(lat1=lat1, lon1=lon1, lat2=lat2, lon2=lon2, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_geodesic_midpoint", **given)

def geo_geodesic_polygon_area(lats=None, lons=None, ellipsoid=None):
    """Area and perimeter of a geodesic polygon on the ellipsoid. The area enclosed by a polygon whose edges are geodesics on the WGS84 or GRS80 ellipsoid, and its perimeter (vertices given as latitude and longitude lists, in either orientation).
    Formula: S = -\\oint \\frac{a^2}{2}\\left[q(\\varphi) - q(\\varphi_c)\\right]d\\lambda,\\quad q(\\varphi) = (1-e^2)\\left[\\frac{\\sin\\varphi}{1-e^2\\sin^2\\varphi} + \\frac{\\operatorname{artanh}(e\\sin\\varphi)}{e}\\right]
    Inputs:
        lats: latitudes of the vertices in order (decimal degrees)
        lons: longitudes of the vertices in the same order (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: area (enclosed area on the ellipsoid), perimeter (perimeter (sum of the geodesic edge lengths))
    See also: help("geo_geodesic_polygon_area")
    """
    given = {k: v for k, v in dict(lats=lats, lons=lons, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_geodesic_polygon_area", **given)

def geo_geodetic_to_ecef(lat=None, lon=None, h=None, ellipsoid=None):
    """Geodetic to geocentric (ECEF) coordinates. Earth-centred, Earth-fixed Cartesian coordinates X, Y, Z of a point given by geodetic latitude, longitude and ellipsoidal height on the WGS84 or GRS80 ellipsoid.
    Formula: X = (N+h)\\cos\\varphi\\cos\\lambda,\\ Y = (N+h)\\cos\\varphi\\sin\\lambda,\\ Z = \\left(N(1-e^2)+h\\right)\\sin\\varphi
    Inputs:
        lat: geodetic latitude (decimal degrees)
        lon: longitude (decimal degrees)
        h: ellipsoidal height
        ellipsoid: reference ellipsoid
    Outputs: X (X (towards latitude 0, longitude 0)), Y (Y (towards longitude 90 E)), Z (Z (towards the north pole))
    See also: help("geo_geodetic_to_ecef")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, h=h, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_geodetic_to_ecef", **given)

def geo_geodetic_to_enu(lat0=None, lon0=None, h0=None, lat=None, lon=None, h=None, ellipsoid=None):
    """Geodetic to local east-north-up (ENU) coordinates. Local tangent-plane coordinates east, north and up of a point relative to an origin (both given by latitude, longitude and ellipsoidal height), and the straight-line (slant) range.
    Formula: \\begin{bmatrix}e\\\\n\\\\u\\end{bmatrix} = \\begin{bmatrix}-\\sin\\lambda_0 & \\cos\\lambda_0 & 0\\\\ -\\sin\\varphi_0\\cos\\lambda_0 & -\\sin\\varphi_0\\sin\\lambda_0 & \\cos\\varphi_0\\\\ \\cos\\varphi_0\\cos\\lambda_0 & \\cos\\varphi_0\\sin\\lambda_0 & \\sin\\varphi_0\\end{bmatrix}\\begin{bmatrix}\\Delta X\\\\ \\Delta Y\\\\ \\Delta Z\\end{bmatrix}
    Inputs:
        lat0: latitude of the local origin (decimal degrees)
        lon0: longitude of the local origin (decimal degrees)
        h0: ellipsoidal height of the origin
        lat: latitude of the point (decimal degrees)
        lon: longitude of the point (decimal degrees)
        h: ellipsoidal height of the point
        ellipsoid: reference ellipsoid
    Outputs: e (east coordinate), n (north coordinate), u (up coordinate), slant_range (straight-line distance from the origin)
    See also: help("geo_geodetic_to_enu")
    """
    given = {k: v for k, v in dict(lat0=lat0, lon0=lon0, h0=h0, lat=lat, lon=lon, h=h, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_geodetic_to_enu", **given)

def geo_geohash_decode(geohash=None):
    """Decode a geohash: cell centre and size. The centre latitude and longitude of a geohash cell and its half-height and half-width in degrees.
    Formula: [\\varphi_{min}, \\varphi_{max}] \\times [\\lambda_{min}, \\lambda_{max}] \\ \\text{by alternate bisection}
    Inputs:
        geohash: geohash string (characters 0-9, b-z without a, i, l, o)
    Outputs: lat_center (latitude of the cell centre), lon_center (longitude of the cell centre), lat_error (half the cell height (degrees)), lon_error (half the cell width (degrees))
    See also: help("geo_geohash_decode")
    """
    given = {k: v for k, v in dict(geohash=geohash).items() if v is not None}
    return _P.solve("geo_geohash_decode", **given)

def geo_geohash_encode(lat=None, lon=None, precision=None):
    """Geohash of a point and its cell. The geohash of a latitude and longitude at a given number of characters, with the centre and half-sizes of the geohash cell.
    Formula: \\text{bits} = \\lambda_1\\varphi_1\\lambda_2\\varphi_2\\ldots,\\quad \\text{character} = \\text{base32}(5\\ \\text{bits})
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        precision: number of geohash characters (1-12)
    Outputs: geohash (geohash), lat_center (latitude of the cell centre), lon_center (longitude of the cell centre), lat_error (half the cell height (degrees)), lon_error (half the cell width (degrees))
    See also: help("geo_geohash_encode")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, precision=precision).items() if v is not None}
    return _P.solve("geo_geohash_encode", **given)

def geo_getis_ord_general_g(y=None, W=None):
    """Getis-Ord general G (global high/low clustering). The Getis-Ord general G statistic of a positive variable with binary spatial weights, its expectation and variance under randomization and the z-score (G above its expectation: high values cluster).
    Formula: G = \\frac{\\sum_i\\sum_{j\\neq i} w_{ij}y_iy_j}{\\sum_i\\sum_{j\\neq i}y_iy_j},\\quad E[G] = \\frac{S_0}{n(n-1)}
    Inputs:
        y: positive values at the n locations
        W: binary spatial weights matrix (0/1, zero diagonal)
    Outputs: G (general G), EG (expected G = S0/(n(n-1))), VG (variance of G under randomization), z_norm (z-score)
    See also: help("geo_getis_ord_general_g")
    """
    given = {k: v for k, v in dict(y=y, W=W).items() if v is not None}
    return _P.solve("geo_getis_ord_general_g", **given)

def geo_gnomonic_forward(lat=None, lon=None, lat0=None, lon0=None, R=None):
    """Gnomonic projection (sphere). x and y of a point in the gnomonic projection (great circles become straight lines) of a sphere of radius R centred on a point.
    Formula: x = \\frac{R\\cos\\varphi\\sin\\Delta\\lambda}{\\cos c},\\quad y = \\frac{R\\left(\\cos\\varphi_0\\sin\\varphi - \\sin\\varphi_0\\cos\\varphi\\cos\\Delta\\lambda\\right)}{\\cos c}
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lat0: latitude of the centre (decimal degrees)
        lon0: longitude of the centre (decimal degrees)
        R: radius of the sphere
    Outputs: x (x), y (y)
    See also: help("geo_gnomonic_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lat0=lat0, lon0=lon0, R=R).items() if v is not None}
    return _P.solve("geo_gnomonic_forward", **given)

def geo_graticule_cell_area(lat1=None, lat2=None, lon1=None, lon2=None, ellipsoid=None):
    """Area of a latitude-longitude cell on the ellipsoid. The area of the region between two parallels and two meridians (a graticule cell or grid square) on the WGS84 or GRS80 ellipsoid, and its share of the whole ellipsoid's surface.
    Formula: A = \\frac{a^2}{2}\\left[q(\\varphi_2) - q(\\varphi_1)\\right](\\lambda_2 - \\lambda_1)
    Inputs:
        lat1: southern latitude (decimal degrees)
        lat2: northern latitude (decimal degrees)
        lon1: western longitude (decimal degrees)
        lon2: eastern longitude (east of lon1) (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: area (area of the cell), fraction_of_ellipsoid (area as a fraction of the ellipsoid's total surface)
    See also: help("geo_graticule_cell_area")
    """
    given = {k: v for k, v in dict(lat1=lat1, lat2=lat2, lon1=lon1, lon2=lon2, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_graticule_cell_area", **given)

def geo_gravity_accessibility(edges=None, opportunities=None, beta=None, impedance=None):
    """Gravity-based (Hansen) accessibility on a road network. The Hansen gravity accessibility of every node of a network: the sum of the opportunities (jobs, services) at the other nodes discounted by a power or negative-exponential function of the shortest-path distance.
    Formula: A_i = \\sum_{j\\ne i} O_j\\,f(d_{ij}),\\quad f(d) = d^{-\\beta}\\ \\text{or}\\ e^{-\\beta d}
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        opportunities: opportunities at nodes 0 .. n-1
        beta: distance-decay parameter
        impedance: impedance function d^-beta or exp(-beta d)
    Outputs: accessibility (accessibility of each node)
    See also: help("geo_gravity_accessibility")
    """
    given = {k: v for k, v in dict(edges=edges, opportunities=opportunities, beta=beta, impedance=impedance).items() if v is not None}
    return _P.solve("geo_gravity_accessibility", **given)

def geo_gravity_model_poisson_fit(T=None, O=None, D=None, d=None):
    """Spatial interaction (gravity) model fitted by Poisson regression. The constant k, the origin and destination mass exponents and the distance-decay exponent of the unconstrained gravity model T = k O^alpha D^beta d^-gamma, fitted to observed flows by Poisson maximum likelihood.
    Formula: T_{ij} \\sim \\mathrm{Poisson}(\\mu_{ij}),\\quad \\ln\\mu_{ij} = \\ln k + \\alpha\\ln O_i + \\beta\\ln D_j - \\gamma\\ln d_{ij}
    Inputs:
        T: observed flows between the pairs
        O: origin masses (e.g. populations)
        D: destination masses
        d: distances between the pairs
    Outputs: k (constant), alpha (origin mass exponent), beta (destination mass exponent), gamma (distance-decay exponent)
    See also: help("geo_gravity_model_poisson_fit")
    """
    given = {k: v for k, v in dict(T=T, O=O, D=D, d=d).items() if v is not None}
    return _P.solve("geo_gravity_model_poisson_fit", **given)

def geo_ground_sample_distance(pixel_pitch=None, focal_length=None, altitude=None, pixels=None):
    """Ground sample distance and swath of a nadir-looking camera. The ground sample distance (pixel footprint) and swath width of a nadir-looking frame camera or scanner from its pixel pitch, focal length, flying height above ground and number of pixels across track.
    Formula: GSD = \\frac{p\\,H}{f},\\quad W = GSD \\times N
    Inputs:
        pixel_pitch: detector pixel pitch
        focal_length: focal length
        altitude: height above the ground
        pixels: number of pixels across track
    Outputs: gsd (ground sample distance), swath (swath width)
    See also: help("geo_ground_sample_distance")
    """
    given = {k: v for k, v in dict(pixel_pitch=pixel_pitch, focal_length=focal_length, altitude=altitude, pixels=pixels).items() if v is not None}
    return _P.solve("geo_ground_sample_distance", **given)

def geo_hillshade(window=None, cell_size=None, sun_azimuth=None, sun_altitude=None):
    """Hillshade (analytical relief shading) of a 3x3 elevation window. The illumination (cosine of the solar incidence angle on the terrain) and the 0-255 hillshade value at the centre of a 3 x 3 elevation window for a sun azimuth and altitude.
    Formula: \\cos i = \\cos Z\\cos S + \\sin Z\\sin S\\cos(A - \\alpha),\\quad H = 255\\max(0, \\cos i)
    Inputs:
        window: 3 x 3 elevations in metres, row 0 to the north
        cell_size: cell size
        sun_azimuth: sun azimuth, clockwise from north (decimal degrees)
        sun_altitude: sun altitude above the horizon (decimal degrees)
    Outputs: illumination (cos(incidence angle) (negative in self-shadow)), hillshade (255 x max(0, illumination))
    See also: help("geo_hillshade")
    """
    given = {k: v for k, v in dict(window=window, cell_size=cell_size, sun_azimuth=sun_azimuth, sun_altitude=sun_altitude).items() if v is not None}
    return _P.solve("geo_hillshade", **given)

def geo_huff_model(edges=None, origin=None, stores=None, attractiveness=None, alpha=None, beta=None):
    """Huff model: probabilities of shopping at each store from an origin (network distances). The Huff probabilities that a consumer at an origin node patronizes each store, from store attractiveness (floor space) and shortest-path distances on a road network.
    Formula: P_{ij} = \\frac{S_j^{\\alpha}d_{ij}^{-\\beta}}{\\sum_k S_k^{\\alpha}d_{ik}^{-\\beta}}
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        origin: origin node
        stores: store nodes
        attractiveness: attractiveness of each store (e.g. floor area)
        alpha: attractiveness exponent
        beta: distance-decay exponent
    Outputs: probabilities (probability of each store), distances (shortest-path distance to each store)
    See also: help("geo_huff_model")
    """
    given = {k: v for k, v in dict(edges=edges, origin=origin, stores=stores, attractiveness=attractiveness, alpha=alpha, beta=beta).items() if v is not None}
    return _P.solve("geo_huff_model", **given)

def geo_idw_interpolation(x=None, y=None, z=None, px=None, py=None, power=None):
    """Inverse distance weighted (IDW) interpolation at a point. The inverse-distance-weighted (Shepard) estimate of a variable at a location from sample points, with a stated power (2 is the usual choice).
    Formula: \\hat z(\\mathbf p) = \\frac{\\sum_i d_i^{-p}z_i}{\\sum_i d_i^{-p}}
    Inputs:
        x: x coordinates of the samples
        y: y coordinates of the samples
        z: sample values
        px: x of the location
        py: y of the location
        power: distance power p (> 0)
    Outputs: estimate (interpolated value)
    See also: help("geo_idw_interpolation")
    """
    given = {k: v for k, v in dict(x=x, y=y, z=z, px=px, py=py, power=power).items() if v is not None}
    return _P.solve("geo_idw_interpolation", **given)

def geo_join_counts(y=None, W=None):
    """Join count statistics of a binary map (BB, BW, WW). The numbers of black-black, black-white and white-white joins between neighbouring areas of a binary (presence/absence) map, and the total number of joins.
    Formula: BB = \\tfrac12\\sum_{i,j} w_{ij}y_iy_j,\\ BW = \\tfrac12\\sum_{i,j} w_{ij}(y_i - y_j)^2,\\ WW = \\tfrac12\\sum_{i,j}w_{ij}(1-y_i)(1-y_j)
    Inputs:
        y: binary variable at the n areas (1 black, 0 white)
        W: binary symmetric contiguity matrix (0/1, zero diagonal)
    Outputs: BB (black-black joins), BW (black-white joins), WW (white-white joins), J (total joins)
    See also: help("geo_join_counts")
    """
    given = {k: v for k, v in dict(y=y, W=W).items() if v is not None}
    return _P.solve("geo_join_counts", **given)

def geo_kernel_density(x=None, y=None, px=None, py=None, bandwidth=None, kernel=None):
    """Kernel density estimate of a point pattern at a location. The two-dimensional kernel density (per unit area, integrating to 1) and the intensity (events per unit area) of a point pattern at a location, with a stated kernel and bandwidth.
    Formula: \\hat f(\\mathbf p) = \\frac1n\\sum_i K_h(\\lVert\\mathbf p - \\mathbf x_i\\rVert),\\quad K^{gauss}_h = \\frac{e^{-u^2/2}}{2\\pi h^2},\\ K^{epa}_h = \\frac{2(1-u^2)}{\\pi h^2},\\ K^{unif}_h = \\frac{1}{\\pi h^2}
    Inputs:
        x: x coordinates of the events
        y: y coordinates of the events
        px: x of the location
        py: y of the location
        bandwidth: bandwidth h (coordinate units)
        kernel: kernel (gaussian with sd h; epanechnikov and uniform with radius h)
    Outputs: density (density (per square coordinate unit, integrates to 1)), intensity (intensity = n x density (events per square unit))
    See also: help("geo_kernel_density")
    """
    given = {k: v for k, v in dict(x=x, y=y, px=px, py=py, bandwidth=bandwidth, kernel=kernel).items() if v is not None}
    return _P.solve("geo_kernel_density", **given)

def geo_knn_weights(x=None, y=None, k=None):
    """k-nearest-neighbour spatial weights. The binary k-nearest-neighbour weights matrix of a set of points (row i marks the k nearest points to point i), its total weight and whether it is symmetric.
    Formula: w_{ij} = 1 \\iff j \\in N_k(i)
    Inputs:
        x: x coordinates
        y: y coordinates
        k: number of neighbours
    Outputs: W (weights matrix (n x n, 0/1)), s0 (sum of all weights (n k)), symmetric (whether W is symmetric)
    See also: help("geo_knn_weights")
    """
    given = {k: v for k, v in dict(x=x, y=y, k=k).items() if v is not None}
    return _P.solve("geo_knn_weights", **given)

def geo_lambert_azimuthal_equal_area_forward(lat=None, lon=None, lat0=None, lon0=None, ellipsoid=None, FE=None, FN=None):
    """Lambert azimuthal equal-area projection (ellipsoidal). Easting and northing of a point in the ellipsoidal oblique Lambert azimuthal equal-area projection about a centre (as in ETRS89-LAEA, EPSG:3035).
    Formula: B = R_q\\sqrt{\\frac{2}{1 + \\sin\\beta_1\\sin\\beta + \\cos\\beta_1\\cos\\beta\\cos\\Delta\\lambda}},\\ x = BD\\cos\\beta\\sin\\Delta\\lambda,\\ y = \\frac{B}{D}\\left(\\cos\\beta_1\\sin\\beta - \\sin\\beta_1\\cos\\beta\\cos\\Delta\\lambda\\right)
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lat0: latitude of the centre (decimal degrees)
        lon0: longitude of the centre (decimal degrees)
        ellipsoid: reference ellipsoid
        FE: false easting (default 0) (optional)
        FN: false northing (default 0) (optional)
    Outputs: x (easting), y (northing)
    See also: help("geo_lambert_azimuthal_equal_area_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lat0=lat0, lon0=lon0, ellipsoid=ellipsoid, FE=FE, FN=FN).items() if v is not None}
    return _P.solve("geo_lambert_azimuthal_equal_area_forward", **given)

def geo_lambert_conformal_conic_forward(lat=None, lon=None, lat1=None, lat2=None, lat0=None, lon0=None, ellipsoid=None, FE=None, FN=None):
    """Lambert conformal conic projection (two standard parallels): coordinates, scale factor and convergence. Easting and northing of a point in the ellipsoidal Lambert conformal conic projection with two standard parallels (EPSG method 9802), with the point scale factor and the grid convergence.
    Formula: n = \\frac{\\ln m_1 - \\ln m_2}{\\ln t_1 - \\ln t_2},\\ \\rho = aFt^n,\\ x = FE + \\rho\\sin\\theta,\\ y = FN + \\rho_0 - \\rho\\cos\\theta,\\ k = \\frac{\\rho n}{am}
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lat1: first standard parallel (decimal degrees)
        lat2: second standard parallel (decimal degrees)
        lat0: latitude of origin (decimal degrees)
        lon0: central meridian (decimal degrees)
        ellipsoid: reference ellipsoid
        FE: false easting (default 0) (optional)
        FN: false northing (default 0) (optional)
    Outputs: x (easting), y (northing), k (point scale factor), gamma (grid convergence (degrees))
    See also: help("geo_lambert_conformal_conic_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lat1=lat1, lat2=lat2, lat0=lat0, lon0=lon0, ellipsoid=ellipsoid, FE=FE, FN=FN).items() if v is not None}
    return _P.solve("geo_lambert_conformal_conic_forward", **given)

def geo_lambert_conformal_conic_inverse(x=None, y=None, lat1=None, lat2=None, lat0=None, lon0=None, ellipsoid=None, FE=None, FN=None):
    """Inverse Lambert conformal conic projection (two standard parallels). Latitude and longitude of a point given by its easting and northing in the ellipsoidal Lambert conformal conic projection with two standard parallels.
    Formula: \\rho = \\operatorname{sgn}(n)\\sqrt{x'^2 + (\\rho_0 - y')^2},\\quad t = \\left(\\frac{\\rho}{aF}\\right)^{1/n},\\quad \\lambda = \\lambda_0 + \\frac{\\theta}{n}
    Inputs:
        x: easting
        y: northing
        lat1: first standard parallel (decimal degrees)
        lat2: second standard parallel (decimal degrees)
        lat0: latitude of origin (decimal degrees)
        lon0: central meridian (decimal degrees)
        ellipsoid: reference ellipsoid
        FE: false easting (default 0) (optional)
        FN: false northing (default 0) (optional)
    Outputs: lat (latitude (degrees)), lon (longitude (degrees))
    See also: help("geo_lambert_conformal_conic_inverse")
    """
    given = {k: v for k, v in dict(x=x, y=y, lat1=lat1, lat2=lat2, lat0=lat0, lon0=lon0, ellipsoid=ellipsoid, FE=FE, FN=FN).items() if v is not None}
    return _P.solve("geo_lambert_conformal_conic_inverse", **given)

def geo_line_of_sight_profile(d=None, z=None, observer_height=None, target_height=None, curvature=None):
    """Line-of-sight visibility along a terrain profile (with Earth curvature and refraction). Which points along a terrain profile are visible from an observer at its start, for given observer and target heights above the ground, optionally with the Earth-curvature and refraction correction.
    Formula: \\text{visible}(i) \\iff z_j < z_{eye} + (z_i + h_t - z_{eye})\\frac{d_j}{d_i}\\ \\forall\\, 0 < j < i,\\quad \\Delta z_{curv} = \\frac{d^2(1-k)}{2R}
    Inputs:
        d: distances along the profile in metres, starting at 0 (the observer)
        z: ground elevations in metres
        observer_height: eye height above the ground
        target_height: target height above the ground
        curvature: none, or the drop d^2 (1 - k)/(2R) with R = 6371 km and k = 0.13
    Outputs: visible (1 if the target over each point is visible, else 0 (the observer's own point is 1)), n_visible (number of visible points beyond the observer)
    See also: help("geo_line_of_sight_profile")
    """
    given = {k: v for k, v in dict(d=d, z=z, observer_height=observer_height, target_height=target_height, curvature=curvature).items() if v is not None}
    return _P.solve("geo_line_of_sight_profile", **given)

def geo_local_getis_ord_gi(y=None, W=None, statistic=None):
    """Local Getis-Ord Gi and Gi* hot-spot statistics. The local Getis-Ord statistic of every location (Gi* includes the location itself, Gi excludes it) with binary weights, and its z-score for hot-spot (positive) and cold-spot (negative) mapping.
    Formula: G_i^* = \\frac{\\sum_j w_{ij}y_j}{\\sum_j y_j},\\quad Z_i = \\frac{G_i - W_i/N}{\\sqrt{\\frac{W_i(N - W_i)}{(N-1)N^2}\\frac{s^2}{\\bar y^2}}}
    Inputs:
        y: positive values at the n locations
        W: binary spatial weights matrix (0/1, zero diagonal)
        statistic: Gi* (the location counts as its own neighbour) or Gi
    Outputs: Gs (local G of each location), Zs (z-score of each location)
    See also: help("geo_local_getis_ord_gi")
    """
    given = {k: v for k, v in dict(y=y, W=W, statistic=statistic).items() if v is not None}
    return _P.solve("geo_local_getis_ord_gi", **given)

def geo_local_morans_i(y=None, W=None):
    """Local Moran's I (LISA) and Moran scatterplot quadrants. The local Moran statistic of every location with row-standardized weights, and its Moran scatterplot quadrant: 1 high-high, 2 low-high, 3 low-low, 4 high-low.
    Formula: I_i = (n-1)\\frac{z_i\\sum_j w_{ij}z_j}{\\sum_k z_k^2}
    Inputs:
        y: values at the n locations
        W: spatial weights matrix (row-standardized internally)
    Outputs: Is (local Moran's I of each location), quadrant (quadrant of each location (1 HH, 2 LH, 3 LL, 4 HL))
    See also: help("geo_local_morans_i")
    """
    given = {k: v for k, v in dict(y=y, W=W).items() if v is not None}
    return _P.solve("geo_local_morans_i", **given)

def geo_look_angles(lat0=None, lon0=None, h0=None, lat=None, lon=None, h=None, ellipsoid=None):
    """Look angles: azimuth, elevation and range from an observer to a target. The azimuth (clockwise from true north), elevation angle above the local horizontal plane and slant range from an observer to a target, both given by latitude, longitude and ellipsoidal height (a satellite, aircraft or summit).
    Formula: A = \\operatorname{atan2}(e, n),\\quad \\varepsilon = \\operatorname{atan2}\\!\\left(u, \\sqrt{e^2+n^2}\\right)
    Inputs:
        lat0: observer latitude (decimal degrees)
        lon0: observer longitude (decimal degrees)
        h0: observer ellipsoidal height
        lat: target latitude (decimal degrees)
        lon: target longitude (decimal degrees)
        h: target ellipsoidal height
        ellipsoid: reference ellipsoid
    Outputs: azimuth (azimuth (degrees clockwise from north)), elevation (elevation angle (degrees, negative below the horizon)), slant_range (straight-line distance)
    See also: help("geo_look_angles")
    """
    given = {k: v for k, v in dict(lat0=lat0, lon0=lon0, h0=h0, lat=lat, lon=lon, h=h, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_look_angles", **given)

def geo_map_scale_from_distances(map_distance=None, ground_distance=None):
    """Map scale (representative fraction) from a map and a ground distance. The scale denominator and representative fraction of a map on which a known ground distance measures a given map distance.
    Formula: S = \\frac{D}{d},\\quad RF = \\frac{1}{S}
    Inputs:
        map_distance: distance on the map
        ground_distance: corresponding ground distance
    Outputs: scale (scale denominator S (scale 1 : S)), rf (representative fraction 1/S)
    See also: help("geo_map_scale_from_distances")
    """
    given = {k: v for k, v in dict(map_distance=map_distance, ground_distance=ground_distance).items() if v is not None}
    return _P.solve("geo_map_scale_from_distances", **given)

def geo_map_scale_ground_distance(map_distance=None, scale=None):
    """Ground distance from a map distance and a representative fraction. The real-world distance represented by a distance measured on a map of scale 1 : scale.
    Formula: D = d \\times S
    Inputs:
        map_distance: distance measured on the map
        scale: scale denominator (1 : scale)
    Outputs: ground_distance (ground distance), ground_km (ground distance in kilometres)
    See also: help("geo_map_scale_ground_distance")
    """
    given = {k: v for k, v in dict(map_distance=map_distance, scale=scale).items() if v is not None}
    return _P.solve("geo_map_scale_ground_distance", **given)

def geo_maximal_covering_location(edges=None, demand=None, candidates=None, p=None, coverage=None):
    """Maximal covering location problem (MCLP) on a network. The largest demand that p facilities, chosen from candidate nodes, can cover within a coverage distance on a road network, and the covered share.
    Formula: \\max_{S\\subseteq C,|S| = p}\\ \\sum_i w_i\\,\\mathbf 1\\left[\\min_{j\\in S}d_{ij}\\le s\\right]
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        demand: demand at nodes 0 .. n-1
        candidates: candidate facility nodes
        p: number of facilities
        coverage: coverage distance (network distance <= coverage counts)
    Outputs: covered (maximum covered demand), fraction (covered share of the total demand)
    See also: help("geo_maximal_covering_location")
    """
    given = {k: v for k, v in dict(edges=edges, demand=demand, candidates=candidates, p=p, coverage=coverage).items() if v is not None}
    return _P.solve("geo_maximal_covering_location", **given)

def geo_mean_center_standard_distance(x=None, y=None):
    """Mean centre and standard distance of a point pattern. The mean centre of a set of points and the standard distance (root-mean-square distance from the mean centre).
    Formula: SD = \\sqrt{\\frac{\\sum_i (x_i - \\bar x)^2 + (y_i - \\bar y)^2}{n}}
    Inputs:
        x: x coordinates
        y: y coordinates
    Outputs: mean_x (x of the mean centre), mean_y (y of the mean centre), std_distance (standard distance)
    See also: help("geo_mean_center_standard_distance")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("geo_mean_center_standard_distance", **given)

def geo_mercator_forward(lat=None, lon=None, lon0=None, lat_ts=None, ellipsoid=None):
    """Mercator projection (ellipsoidal): coordinates and scale factor. x and y of a point in the ellipsoidal Mercator projection with a central meridian and standard parallel (lat_ts = 0 is World Mercator, EPSG:3395), with the point scale factor.
    Formula: x = k_0a(\\lambda-\\lambda_0),\\quad y = k_0a\\left[\\operatorname{arsinh}(\\tan\\varphi) - e\\operatorname{artanh}(e\\sin\\varphi)\\right],\\quad k = \\frac{k_0\\sqrt{1-e^2\\sin^2\\varphi}}{\\cos\\varphi}
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lon0: central meridian (decimal degrees)
        lat_ts: latitude of true scale (standard parallel) (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: x (easting), y (northing), k (point scale factor)
    See also: help("geo_mercator_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lon0=lon0, lat_ts=lat_ts, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_mercator_forward", **given)

def geo_mercator_inverse(x=None, y=None, lon0=None, lat_ts=None, ellipsoid=None):
    """Inverse Mercator projection (ellipsoidal). Latitude and longitude of a point given by its x and y in the ellipsoidal Mercator projection with a central meridian and standard parallel.
    Formula: \\psi = \\frac{y}{k_0a},\\quad \\tau' = \\sinh\\psi,\\quad \\tau = \\tan\\varphi:\\ \\tau\\sqrt{1+\\sigma^2} - \\sigma\\sqrt{1+\\tau^2} = \\tau'
    Inputs:
        x: easting
        y: northing
        lon0: central meridian (decimal degrees)
        lat_ts: latitude of true scale (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: lat (latitude (degrees)), lon (longitude (degrees))
    See also: help("geo_mercator_inverse")
    """
    given = {k: v for k, v in dict(x=x, y=y, lon0=lon0, lat_ts=lat_ts, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_mercator_inverse", **given)

def geo_meridian_arc(lat1=None, lat2=None, ellipsoid=None):
    """Meridian arc length between two latitudes. The distance along a meridian of the WGS84 or GRS80 ellipsoid between two latitudes, and the meridian distance of each latitude from the equator.
    Formula: m(\\varphi) = \\frac{a}{1+n}\\left[\\left(1+\\tfrac{n^2}{4}+\\tfrac{n^4}{64}\\right)\\varphi - \\tfrac32\\left(n-\\tfrac{n^3}{8}\\right)\\sin2\\varphi + \\tfrac{15}{16}\\left(n^2-\\tfrac{n^4}{4}\\right)\\sin4\\varphi - \\tfrac{35}{48}n^3\\sin6\\varphi + \\tfrac{315}{512}n^4\\sin8\\varphi\\right]
    Inputs:
        lat1: first latitude (decimal degrees)
        lat2: second latitude (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: distance (meridian arc length between the latitudes), m1 (meridian distance from the equator to lat1 (negative south)), m2 (meridian distance from the equator to lat2 (negative south))
    See also: help("geo_meridian_arc")
    """
    given = {k: v for k, v in dict(lat1=lat1, lat2=lat2, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_meridian_arc", **given)

def geo_mgrs_encode(lat=None, lon=None):
    """MGRS grid reference of a point (1 m). The Military Grid Reference System (MGRS / USNG) reference of a WGS84 latitude and longitude to 1 m: zone, latitude band, 100 km square letters and 5-digit easting and northing.
    Formula: \\text{MGRS} = z\\,B\\,C_{100k}R_{100k}\\,\\lfloor E\\rfloor \\bmod 10^5\\,\\lfloor N\\rfloor \\bmod 10^5
    Inputs:
        lat: latitude (WGS84) (decimal degrees)
        lon: longitude (WGS84) (decimal degrees)
    Outputs: mgrs (MGRS reference (no spaces))
    See also: help("geo_mgrs_encode")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon).items() if v is not None}
    return _P.solve("geo_mgrs_encode", **given)

def geo_mollweide_forward(lat=None, lon=None, lon0=None, R=None):
    """Mollweide equal-area projection (sphere). x and y of a point in the Mollweide (homalographic) equal-area projection of a sphere of radius R.
    Formula: 2\\theta + \\sin2\\theta = \\pi\\sin\\varphi,\\quad x = \\frac{2\\sqrt2}{\\pi}R\\,\\Delta\\lambda\\cos\\theta,\\quad y = \\sqrt2R\\sin\\theta
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lon0: central meridian (decimal degrees)
        R: radius of the sphere
    Outputs: x (x), y (y)
    See also: help("geo_mollweide_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lon0=lon0, R=R).items() if v is not None}
    return _P.solve("geo_mollweide_forward", **given)

def geo_morans_i(y=None, W=None, transform=None):
    """Global Moran's I spatial autocorrelation with normal and randomization inference. Global Moran's I of a variable observed at n locations with a given spatial weights matrix, its expectation and variance under normality and under randomization, z-scores and two-sided p-values.
    Formula: I = \\frac{n}{S_0}\\frac{\\sum_i\\sum_j w_{ij}z_iz_j}{\\sum_i z_i^2},\\quad E[I] = -\\frac{1}{n-1},\\quad V_N[I] = \\frac{n^2S_1 - nS_2 + 3S_0^2}{(n^2-1)S_0^2} - E[I]^2
    Inputs:
        y: values at the n locations
        W: spatial weights matrix (n x n, zero diagonal, row i lists the weights of i's neighbours)
        transform: row-standardize the weights (row) or use them as given (none)
    Outputs: I (Moran's I), EI (expected I = -1/(n-1)), VI_norm (variance under normality), z_norm (z-score under normality), p_norm (two-sided p-value under normality), VI_rand (variance under randomization), z_rand (z-score under randomization), p_rand (two-sided p-value under randomization)
    See also: help("geo_morans_i")
    """
    given = {k: v for k, v in dict(y=y, W=W, transform=transform).items() if v is not None}
    return _P.solve("geo_morans_i", **given)

def geo_nearest_neighbour_index(x=None, y=None, area=None):
    """Nearest-neighbour index (Clark-Evans ratio) of a point pattern. The mean observed nearest-neighbour distance of a point pattern, the mean expected under complete spatial randomness in a study area, their ratio R (R < 1 clustered, R > 1 dispersed), the z-score and two-sided p-value.
    Formula: R = \\frac{\\bar d_{obs}}{0.5/\\sqrt{n/A}},\\quad z = \\frac{\\bar d_{obs} - \\bar d_{exp}}{0.26136/\\sqrt{n^2/A}}
    Inputs:
        x: x coordinates of the points
        y: y coordinates of the points
        area: area of the study region (square coordinate units)
    Outputs: d_obs (mean observed nearest-neighbour distance), d_exp (expected mean distance 0.5/sqrt(n/A)), R (nearest-neighbour index d_obs/d_exp), z (z-score), p_value (two-sided p-value)
    See also: help("geo_nearest_neighbour_index")
    """
    given = {k: v for k, v in dict(x=x, y=y, area=area).items() if v is not None}
    return _P.solve("geo_nearest_neighbour_index", **given)

def geo_network_connectivity_indices(edges=None):
    """Network connectivity indices: cyclomatic number, alpha, beta and gamma. The graph-theoretic connectivity measures of a (planar) transport network: vertices, edges, components, cyclomatic number and Kansky's alpha, beta and gamma indices.
    Formula: \\mu = e - v + p,\\quad \\alpha = \\frac{e - v + p}{2v - 5},\\quad \\beta = \\frac{e}{v},\\quad \\gamma = \\frac{e}{3(v-2)}
    Inputs:
        edges: network edges between nodes numbered from 0 (lengths, if given, are ignored)
    Outputs: vertices (number of vertices v), edges (number of distinct edges e), components (connected components p), cyclomatic (cyclomatic number e - v + p), alpha ((e - v + p)/(2v - 5)), beta (e / v), gamma (e / (3(v - 2)))
    See also: help("geo_network_connectivity_indices")
    """
    given = {k: v for k, v in dict(edges=edges).items() if v is not None}
    return _P.solve("geo_network_connectivity_indices", **given)

def geo_ordinary_kriging(x=None, y=None, z=None, px=None, py=None, model=None, nugget=None, sill=None, range=None):
    """Ordinary kriging estimate and kriging variance at a point. The ordinary kriging estimate of a variable at a location from samples, with a given variogram model (nugget, sill, range), and the kriging variance.
    Formula: \\begin{bmatrix}\\Gamma & \\mathbf 1\\\\ \\mathbf 1^T & 0\\end{bmatrix}\\begin{bmatrix}\\boldsymbol\\lambda\\\\ \\mu\\end{bmatrix} = \\begin{bmatrix}\\boldsymbol\\gamma_0\\\\ 1\\end{bmatrix},\\quad \\hat z = \\boldsymbol\\lambda^T\\mathbf z,\\quad \\sigma^2_{OK} = \\boldsymbol\\lambda^T\\boldsymbol\\gamma_0 + \\mu
    Inputs:
        x: x coordinates of the samples
        y: y coordinates of the samples
        z: sample values
        px: x of the location
        py: y of the location
        model: variogram model (pykrige parameterization)
        nugget: nugget
        sill: sill (nugget + partial sill)
        range: range (practical range for exponential and gaussian)
    Outputs: estimate (kriging estimate), variance (kriging variance)
    See also: help("geo_ordinary_kriging")
    """
    given = {k: v for k, v in dict(x=x, y=y, z=z, px=px, py=py, model=model, nugget=nugget, sill=sill, range=range).items() if v is not None}
    return _P.solve("geo_ordinary_kriging", **given)

def geo_orthographic_forward(lat=None, lon=None, lat0=None, lon0=None, R=None):
    """Orthographic projection (sphere). x and y of a point in the orthographic projection (the view of a globe from infinitely far away) of a sphere of radius R centred on a point.
    Formula: x = R\\cos\\varphi\\sin\\Delta\\lambda,\\quad y = R\\left(\\cos\\varphi_0\\sin\\varphi - \\sin\\varphi_0\\cos\\varphi\\cos\\Delta\\lambda\\right)
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lat0: latitude of the centre (decimal degrees)
        lon0: longitude of the centre (decimal degrees)
        R: radius of the sphere
    Outputs: x (x), y (y)
    See also: help("geo_orthographic_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lat0=lat0, lon0=lon0, R=R).items() if v is not None}
    return _P.solve("geo_orthographic_forward", **given)

def geo_p_median(edges=None, demand=None, candidates=None, p=None):
    """p-median facility location on a network. The p facility sites, chosen from candidate nodes, that minimize the total demand-weighted shortest-path distance from every node to its nearest open facility.
    Formula: \\min_{S\\subseteq C, |S| = p}\\ \\sum_i w_i\\min_{j\\in S} d_{ij}
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        demand: demand at nodes 0 .. n-1
        candidates: candidate facility nodes
        p: number of facilities to open
    Outputs: objective (minimum total weighted distance), facilities (chosen facility nodes (ascending)), mean_distance (demand-weighted mean distance)
    See also: help("geo_p_median")
    """
    given = {k: v for k, v in dict(edges=edges, demand=demand, candidates=candidates, p=p).items() if v is not None}
    return _P.solve("geo_p_median", **given)

def geo_parallel_arc(lat=None, lon1=None, lon2=None, ellipsoid=None):
    """Arc length along a parallel of latitude. The distance along a parallel of latitude between two longitudes (the shorter way round) on the WGS84 or GRS80 ellipsoid, and the radius of the parallel.
    Formula: s = N(\\varphi)\\cos\\varphi\\,|\\Delta\\lambda|,\\quad N = \\frac{a}{\\sqrt{1-e^2\\sin^2\\varphi}}
    Inputs:
        lat: latitude of the parallel (decimal degrees)
        lon1: first longitude (decimal degrees)
        lon2: second longitude (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: distance (arc length along the parallel), radius (radius of the parallel N cos(phi))
    See also: help("geo_parallel_arc")
    """
    given = {k: v for k, v in dict(lat=lat, lon1=lon1, lon2=lon2, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_parallel_arc", **given)

def geo_polar_stereographic_forward(lat=None, lon=None, pole=None, lat_ts=None, lon0=None, ellipsoid=None, FE=None, FN=None):
    """Polar stereographic projection (standard parallel): coordinates and scale factor. Easting and northing of a point in the ellipsoidal polar stereographic projection defined by a latitude of true scale (EPSG variant B, as in EPSG:3413 and EPSG:3031), with the point scale factor.
    Formula: \\rho = a\\,m_c\\frac{t}{t_c},\\quad t = e^{-\\psi},\\quad x = FE + \\rho\\sin\\Delta\\lambda,\\ y = FN \\mp \\rho\\cos\\Delta\\lambda,\\quad k = \\frac{\\rho}{am}
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        pole: pole at the projection centre
        lat_ts: latitude of true scale (decimal degrees)
        lon0: longitude of the downward (north pole) or upward (south pole) y axis (decimal degrees)
        ellipsoid: reference ellipsoid
        FE: false easting (default 0) (optional)
        FN: false northing (default 0) (optional)
    Outputs: x (easting), y (northing), k (point scale factor)
    See also: help("geo_polar_stereographic_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, pole=pole, lat_ts=lat_ts, lon0=lon0, ellipsoid=ellipsoid, FE=FE, FN=FN).items() if v is not None}
    return _P.solve("geo_polar_stereographic_forward", **given)

def geo_polygon_compactness(x=None, y=None):
    """Shape compactness indices of a polygon (Polsby-Popper, Schwartzberg, convex hull, Reock). Area, perimeter and the standard compactness measures of a polygon in projected coordinates (used for districts and land parcels): Polsby-Popper, Schwartzberg, convex-hull ratio and Reock.
    Formula: PP = \\frac{4\\pi A}{P^2},\\quad S = \\frac{P}{2\\sqrt{\\pi A}},\\quad C_H = \\frac{A}{A_{hull}},\\quad R = \\frac{A}{\\pi r_{mec}^2}
    Inputs:
        x: x coordinates of the vertices in order (not repeating the first)
        y: y coordinates of the vertices
    Outputs: area (area (square coordinate units)), perimeter (perimeter (coordinate units)), polsby_popper (4 pi A / P^2), schwartzberg (P / (2 sqrt(pi A))), convex_hull_ratio (area / convex hull area), reock (area / area of the minimum enclosing circle)
    See also: help("geo_polygon_compactness")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("geo_polygon_compactness", **given)

def geo_quadrat_test(x=None, y=None, nx=None, ny=None):
    """Quadrat analysis: chi-square test of complete spatial randomness. Counts of points in an nx x ny grid of quadrats over the bounding rectangle of a point pattern, the chi-square statistic against complete spatial randomness, its p-value and the variance-to-mean ratio.
    Formula: \\chi^2 = \\sum_{c}\\frac{(O_c - E)^2}{E},\\quad E = \\frac{n}{n_xn_y},\\quad VMR = \\frac{\\chi^2}{n_xn_y - 1}
    Inputs:
        x: x coordinates of the points
        y: y coordinates of the points
        nx: number of quadrat columns
        ny: number of quadrat rows
    Outputs: chi2 (chi-square statistic), df (degrees of freedom (cells - 1)), p_value (upper-tail p-value), vmr (variance-to-mean ratio of the counts (chi2/df)), counts (count of each quadrat, row by row from the south-west)
    See also: help("geo_quadrat_test")
    """
    given = {k: v for k, v in dict(x=x, y=y, nx=nx, ny=ny).items() if v is not None}
    return _P.solve("geo_quadrat_test", **given)

def geo_radii_of_curvature(lat=None, ellipsoid=None):
    """Radii of curvature of the ellipsoid at a latitude. The meridional radius of curvature M, the prime-vertical radius of curvature N and the Gaussian mean radius sqrt(MN) of the WGS84 or GRS80 ellipsoid at a latitude.
    Formula: M = \\frac{a(1-e^2)}{(1-e^2\\sin^2\\varphi)^{3/2}},\\quad N = \\frac{a}{\\sqrt{1-e^2\\sin^2\\varphi}},\\quad R_G = \\sqrt{MN}
    Inputs:
        lat: latitude (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: M (meridional radius of curvature), N (prime-vertical radius of curvature), R_gauss (Gaussian mean radius sqrt(M N))
    See also: help("geo_radii_of_curvature")
    """
    given = {k: v for k, v in dict(lat=lat, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_radii_of_curvature", **given)

def geo_rank_size_rule(populations=None):
    """Rank-size rule (Zipf) fit of a settlement system. The Zipf exponent q and fitted size of the largest city from a log-log regression of population on rank (P_r = P_1 r^-q), the R^2 of the fit and the two-city primacy ratio.
    Formula: \\ln P_r = \\ln P_1 - q\\ln r
    Inputs:
        populations: populations of the settlements (any order)
    Outputs: q (rank-size exponent (1 is Zipf's law)), P1_fit (fitted population of rank 1), r_squared (R^2 of the log-log fit), primacy (largest / second largest population)
    See also: help("geo_rank_size_rule")
    """
    given = {k: v for k, v in dict(populations=populations).items() if v is not None}
    return _P.solve("geo_rank_size_rule", **given)

def geo_rhumb_line_destination(lat1=None, lon1=None, bearing=None, distance=None, ellipsoid=None):
    """Destination along a rhumb line (loxodrome) on the ellipsoid. The point reached by travelling a given distance on a constant bearing (rhumb line) from a start point on the WGS84 or GRS80 ellipsoid.
    Formula: m_2 = m_1 + s\\cos\\alpha,\\quad \\Delta\\lambda = \\tan\\alpha\\,(\\psi_2 - \\psi_1)
    Inputs:
        lat1: latitude of the start point (decimal degrees)
        lon1: longitude of the start point (decimal degrees)
        bearing: constant bearing, clockwise from north (decimal degrees)
        distance: distance travelled
        ellipsoid: reference ellipsoid
    Outputs: lat2 (latitude of the destination (degrees)), lon2 (longitude of the destination (degrees))
    See also: help("geo_rhumb_line_destination")
    """
    given = {k: v for k, v in dict(lat1=lat1, lon1=lon1, bearing=bearing, distance=distance, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_rhumb_line_destination", **given)

def geo_rhumb_line_inverse(lat1=None, lon1=None, lat2=None, lon2=None, ellipsoid=None):
    """Rhumb-line (loxodrome) distance and bearing on the ellipsoid. The constant bearing and the length of the rhumb line (loxodrome) between two points on the WGS84 or GRS80 ellipsoid, the shorter way round in longitude.
    Formula: \\tan\\alpha = \\frac{\\Delta\\lambda}{\\Delta\\psi},\\quad s = \\frac{\\Delta m}{\\cos\\alpha},\\quad \\psi = \\operatorname{arsinh}(\\tan\\varphi) - e\\operatorname{artanh}(e\\sin\\varphi)
    Inputs:
        lat1: latitude of the start point (decimal degrees)
        lon1: longitude of the start point (decimal degrees)
        lat2: latitude of the end point (decimal degrees)
        lon2: longitude of the end point (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: distance (rhumb-line length), bearing (constant bearing (degrees clockwise from north))
    See also: help("geo_rhumb_line_inverse")
    """
    given = {k: v for k, v in dict(lat1=lat1, lon1=lon1, lat2=lat2, lon2=lon2, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_rhumb_line_inverse", **given)

def geo_ripley_k(x=None, y=None, d=None):
    """Ripley's K and L functions of a point pattern. Ripley's K function and its variance-stabilized L function at given distances for a point pattern, without edge correction, in the bounding rectangle of the points.
    Formula: \\hat K(d) = \\frac{A}{n^2}\\sum_{i\\ne j}\\mathbf{1}(d_{ij} < d),\\quad L(d) = \\sqrt{K(d)/\\pi}
    Inputs:
        x: x coordinates of the points
        y: y coordinates of the points
        d: distances at which to evaluate K
    Outputs: K (K(d) at each distance), L (L(d) = sqrt(K/pi) at each distance), area (area of the bounding rectangle)
    See also: help("geo_ripley_k")
    """
    given = {k: v for k, v in dict(x=x, y=y, d=d).items() if v is not None}
    return _P.solve("geo_ripley_k", **given)

def geo_segregation_evenness(x=None, t=None):
    """Residential segregation (evenness): dissimilarity, Gini and Theil entropy indices. The evenness dimension of residential segregation of a group across areal units (census tracts): Duncan's index of dissimilarity, the segregation Gini index and Theil's entropy index H.
    Formula: D = \\frac{\\sum_i t_i|p_i - P|}{2TP(1-P)},\\quad G = \\frac{\\sum_i\\sum_j t_it_j|p_i - p_j|}{2T^2P(1-P)},\\quad H = \\sum_i\\frac{t_i(E - E_i)}{ET}
    Inputs:
        x: group count in each areal unit
        t: total population of each areal unit
    Outputs: dissimilarity (index of dissimilarity D), gini (Gini segregation index), theil_h (Theil's information theory index H)
    See also: help("geo_segregation_evenness")
    """
    given = {k: v for k, v in dict(x=x, t=t).items() if v is not None}
    return _P.solve("geo_segregation_evenness", **given)

def geo_segregation_exposure(x=None, t=None):
    """Residential segregation (exposure): isolation, interaction and correlation ratio. The exposure dimension of residential segregation: the isolation index xPx (probability that a group member meets a member of the same group in their unit), the interaction (exposure) index xPy and the correlation ratio eta^2.
    Formula: {}_xP^*_x = \\sum_i\\frac{x_i}{X}\\frac{x_i}{t_i},\\quad {}_xP^*_y = \\sum_i\\frac{x_i}{X}\\frac{y_i}{t_i},\\quad \\eta^2 = \\frac{{}_xP^*_x - P}{1-P}
    Inputs:
        x: group count in each areal unit
        t: total population of each areal unit
    Outputs: isolation (isolation index xPx), exposure (interaction index xPy), correlation_ratio (correlation ratio (xPx - P)/(1 - P))
    See also: help("geo_segregation_exposure")
    """
    given = {k: v for k, v in dict(x=x, t=t).items() if v is not None}
    return _P.solve("geo_segregation_exposure", **given)

def geo_service_area(edges=None, source=None, cutoff=None):
    """Network service area (isochrone) of a facility. The nodes of a road network within a travel-cost cutoff of a facility (the service area or isochrone), their number and the largest distance reached.
    Formula: SA(s, c) = \\{v : d(s, v) \\le c\\}
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        source: facility node
        cutoff: maximum network distance or travel time
    Outputs: reachable (nodes within the cutoff (ascending)), count (number of nodes reached (the facility included)), farthest (largest network distance within the cutoff)
    See also: help("geo_service_area")
    """
    given = {k: v for k, v in dict(edges=edges, source=source, cutoff=cutoff).items() if v is not None}
    return _P.solve("geo_service_area", **given)

def geo_shimbel_index(edges=None):
    """Shimbel accessibility index of every node. The Shimbel (total shortest-path distance) index of every node of a connected network, the network total (dispersion) and the most accessible node (smallest index).
    Formula: A_i = \\sum_j d_{ij},\\quad D(G) = \\sum_i A_i
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
    Outputs: shimbel (sum of shortest-path distances from each node), total (network dispersion (sum over all nodes)), most_accessible (node with the smallest Shimbel index (lowest number on ties))
    See also: help("geo_shimbel_index")
    """
    given = {k: v for k, v in dict(edges=edges).items() if v is not None}
    return _P.solve("geo_shimbel_index", **given)

def geo_sinusoidal_forward(lat=None, lon=None, lon0=None, ellipsoid=None):
    """Sinusoidal equal-area projection (ellipsoidal). x and y of a point in the ellipsoidal sinusoidal (Sanson-Flamsteed) equal-area projection, as used for MODIS land grids.
    Formula: x = \\frac{a\\cos\\varphi}{\\sqrt{1-e^2\\sin^2\\varphi}}(\\lambda - \\lambda_0),\\quad y = m(\\varphi)
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lon0: central meridian (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: x (easting), y (northing)
    See also: help("geo_sinusoidal_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lon0=lon0, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_sinusoidal_forward", **given)

def geo_slope_aspect_horn(window=None, cell_size=None):
    """Slope and aspect of a 3x3 elevation window (Horn's method). The slope (degrees and per cent) and aspect (downslope direction, degrees clockwise from north) at the centre cell of a 3 x 3 window of a digital elevation model, by Horn's third-order finite differences.
    Formula: \\frac{\\partial z}{\\partial x} = \\frac{(z_3 + 2z_6 + z_9) - (z_1 + 2z_4 + z_7)}{8\\Delta},\\ \\frac{\\partial z}{\\partial y} = \\frac{(z_1 + 2z_2 + z_3) - (z_7 + 2z_8 + z_9)}{8\\Delta},\\ S = \\arctan\\lVert\\nabla z\\rVert
    Inputs:
        window: 3 x 3 elevations in metres, row 0 to the north, column 0 to the west
        cell_size: cell size (square cells)
    Outputs: slope_deg (slope (degrees)), slope_percent (slope (per cent)), aspect_deg (aspect: downslope direction clockwise from north (none for a flat window))
    See also: help("geo_slope_aspect_horn")
    """
    given = {k: v for k, v in dict(window=window, cell_size=cell_size).items() if v is not None}
    return _P.solve("geo_slope_aspect_horn", **given)

def geo_spatial_lag(y=None, W=None, transform=None):
    """Spatial lag of a variable. The spatial lag W y of a variable: for row-standardized weights, the average of each location's neighbours; otherwise the weighted sum.
    Formula: [Wy]_i = \\sum_j w_{ij}y_j
    Inputs:
        y: values at the n locations
        W: spatial weights matrix (n x n, zero diagonal, row i lists the weights of i's neighbours)
        transform: row-standardize the weights (row) or use them as given (none)
    Outputs: lag (spatial lag at each location)
    See also: help("geo_spatial_lag")
    """
    given = {k: v for k, v in dict(y=y, W=W, transform=transform).items() if v is not None}
    return _P.solve("geo_spatial_lag", **given)

def geo_standard_deviational_ellipse(x=None, y=None):
    """Standard deviational ellipse of a point pattern. The semi-axes of the standard deviational ellipse of a point pattern (CrimeStat correction sqrt(2) sqrt(n/(n-2))) and the orientation of its major axis.
    Formula: s_{x,y} = \\sqrt{\\frac{2n}{n-2}\\lambda_{1,2}},\\quad \\lambda_{1,2} = \\frac{s_{xx}+s_{yy}}{2} \\pm \\sqrt{\\frac{(s_{xx}-s_{yy})^2}{4} + s_{xy}^2}
    Inputs:
        x: x coordinates
        y: y coordinates
    Outputs: sx (semi-major axis), sy (semi-minor axis), orientation (bearing of the major axis, degrees clockwise from north (y axis), in [0, 180))
    See also: help("geo_standard_deviational_ellipse")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("geo_standard_deviational_ellipse", **given)

def geo_terrain_curvature(window=None, cell_size=None):
    """Terrain curvature: total, profile and plan curvature (Zevenbergen-Thorne). The total, profile (along the slope) and plan (across the slope) curvature at the centre of a 3 x 3 elevation window from the Zevenbergen-Thorne partial quartic surface.
    Formula: K = -2(D+E),\\quad K_{prof} = \\frac{-2(DG^2 + EH^2 + FGH)}{G^2 + H^2},\\quad K_{plan} = \\frac{2(DH^2 + EG^2 - FGH)}{G^2 + H^2}
    Inputs:
        window: 3 x 3 elevations in metres, row 0 to the north
        cell_size: cell size
    Outputs: curvature (total curvature -2(D + E) (1/m; positive upwardly convex)), profile (profile curvature (1/m)), plan (plan curvature (1/m))
    See also: help("geo_terrain_curvature")
    """
    given = {k: v for k, v in dict(window=window, cell_size=cell_size).items() if v is not None}
    return _P.solve("geo_terrain_curvature", **given)

def geo_terrain_ruggedness(window=None):
    """Terrain ruggedness index (Riley), topographic position index and local relief. Riley's terrain ruggedness index (root of the summed squared elevation differences to the 8 neighbours), the topographic position index (centre minus neighbour mean) and the local relief of a 3 x 3 window.
    Formula: TRI = \\sqrt{\\sum_{i=1}^{8}(z_i - z_0)^2},\\quad TPI = z_0 - \\frac18\\sum_{i=1}^{8}z_i
    Inputs:
        window: 3 x 3 elevations in metres
    Outputs: TRI (terrain ruggedness index (m)), TPI (topographic position index (m)), relief (maximum minus minimum elevation (m))
    See also: help("geo_terrain_ruggedness")
    """
    given = {k: v for k, v in dict(window=window).items() if v is not None}
    return _P.solve("geo_terrain_ruggedness", **given)

def geo_tissot_indicatrix(projection=None, lat=None, lon=None):
    """Tissot's indicatrix: scale factors and distortion of a projection at a point. The meridian and parallel scale factors h and k, the angle between meridian and parallel, the semi-axes a and b of Tissot's indicatrix, the maximum angular distortion and the areal scale of a world projection of the sphere at a point.
    Formula: a' = \\sqrt{h^2+k^2+2hk\\sin\\theta'},\\ b' = \\sqrt{h^2+k^2-2hk\\sin\\theta'},\\ a = \\tfrac{a'+b'}{2},\\ b = \\tfrac{a'-b'}{2},\\ \\omega = 2\\arcsin\\frac{a-b}{a+b},\\ s = hk\\sin\\theta'
    Inputs:
        projection: projection (spherical form, central meridian 0)
        lat: latitude (decimal degrees)
        lon: longitude measured from the central meridian (decimal degrees)
    Outputs: h (scale factor along the meridian), k (scale factor along the parallel), theta_prime (angle between the projected meridian and parallel (degrees, at most 90)), a (maximum scale factor (semi-major axis)), b (minimum scale factor (semi-minor axis)), omega (maximum angular distortion (degrees)), s (areal scale factor)
    See also: help("geo_tissot_indicatrix")
    """
    given = {k: v for k, v in dict(projection=projection, lat=lat, lon=lon).items() if v is not None}
    return _P.solve("geo_tissot_indicatrix", **given)

def geo_toa_reflectance(radiance=None, esun=None, doy=None, sun_elevation=None):
    """Top-of-atmosphere reflectance from at-sensor radiance. The top-of-atmosphere (planetary) reflectance of a pixel from its at-sensor spectral radiance, the band's mean exoatmospheric solar irradiance ESUN, the day of year and the sun elevation, with the Earth-Sun distance.
    Formula: \\rho_{TOA} = \\frac{\\pi L_\\lambda d^2}{ESUN_\\lambda\\cos\\theta_s},\\quad \\frac{1}{d^2} = 1.00011 + 0.034221\\cos\\Gamma + 0.00128\\sin\\Gamma + 0.000719\\cos2\\Gamma + 0.000077\\sin2\\Gamma
    Inputs:
        radiance: at-sensor spectral radiance (W/(m^2 sr um))
        esun: band mean exoatmospheric solar irradiance ESUN (W/(m^2 um))
        doy: day of year (1-366)
        sun_elevation: sun elevation angle (decimal degrees)
    Outputs: earth_sun_distance (Earth-Sun distance (astronomical units)), reflectance (top-of-atmosphere reflectance)
    See also: help("geo_toa_reflectance")
    """
    given = {k: v for k, v in dict(radiance=radiance, esun=esun, doy=doy, sun_elevation=sun_elevation).items() if v is not None}
    return _P.solve("geo_toa_reflectance", **given)

def geo_transverse_mercator_forward(lat=None, lon=None, lat0=None, lon0=None, k0=None, ellipsoid=None, FE=None, FN=None):
    """Transverse Mercator projection: coordinates, scale factor and grid convergence. Easting and northing of a point in a transverse Mercator projection with a given origin, central-meridian scale factor and false origin on the WGS84 or GRS80 ellipsoid, with the point scale factor and the grid convergence.
    Formula: \\xi = \\xi' + \\sum_{j=1}^{6}\\alpha_j\\sin2j\\xi'\\cosh2j\\eta',\\quad \\eta = \\eta' + \\sum_{j=1}^{6}\\alpha_j\\cos2j\\xi'\\sinh2j\\eta',\\quad x = FE + k_0A\\eta,\\ y = FN + k_0A(\\xi - \\xi_0)
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        lat0: latitude of origin (decimal degrees)
        lon0: central meridian (decimal degrees)
        k0: scale factor on the central meridian
        ellipsoid: reference ellipsoid
        FE: false easting (default 0) (optional)
        FN: false northing (default 0) (optional)
    Outputs: x (easting), y (northing), k (point scale factor), gamma (grid convergence (degrees, positive east of the central meridian in the north))
    See also: help("geo_transverse_mercator_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, lat0=lat0, lon0=lon0, k0=k0, ellipsoid=ellipsoid, FE=FE, FN=FN).items() if v is not None}
    return _P.solve("geo_transverse_mercator_forward", **given)

def geo_trend_surface(x=None, y=None, z=None, order=None):
    """Polynomial trend surface (first or second order) by least squares. The coefficients and R^2 of a first-order (plane) or second-order (quadratic) trend surface fitted to sampled values by least squares.
    Formula: z = b_0 + b_1x + b_2y\\ \\left[+\\, b_3x^2 + b_4xy + b_5y^2\\right]
    Inputs:
        x: x coordinates
        y: y coordinates
        z: values
        order: order of the surface (1 or 2)
    Outputs: coefficients (b0, b1 (x), b2 (y)[, b3 (x^2), b4 (xy), b5 (y^2)]), r_squared (coefficient of determination)
    See also: help("geo_trend_surface")
    """
    given = {k: v for k, v in dict(x=x, y=y, z=z, order=order).items() if v is not None}
    return _P.solve("geo_trend_surface", **given)

def geo_two_step_floating_catchment(edges=None, population=None, supply_nodes=None, capacity=None, threshold=None):
    """Two-step floating catchment area (2SFCA) accessibility. The 2SFCA spatial accessibility of every node to services (doctors, schools): supply-to-population ratios within each site's catchment, summed over the sites within reach of each node.
    Formula: R_j = \\frac{S_j}{\\sum_{k: d_{kj}\\le d_0}P_k},\\quad A_i = \\sum_{j: d_{ij}\\le d_0}R_j
    Inputs:
        edges: undirected network as weighted edges between nodes numbered 0 .. n-1
        population: population at nodes 0 .. n-1
        supply_nodes: nodes with a service site
        capacity: capacity of each site (e.g. physicians)
        threshold: catchment threshold (network distance)
    Outputs: accessibility (accessibility of each node (supply per person)), ratios (supply-to-population ratio of each site)
    See also: help("geo_two_step_floating_catchment")
    """
    given = {k: v for k, v in dict(edges=edges, population=population, supply_nodes=supply_nodes, capacity=capacity, threshold=threshold).items() if v is not None}
    return _P.solve("geo_two_step_floating_catchment", **given)

def geo_utm_forward(lat=None, lon=None, ellipsoid=None):
    """Latitude and longitude to UTM coordinates (with scale factor and convergence). UTM zone, hemisphere, easting and northing of a point on the WGS84 or GRS80 ellipsoid, with the point scale factor and grid convergence.
    Formula: E = 500\\,000 + 0.9996\\,A\\eta,\\quad N = N_0 + 0.9996\\,A\\xi
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        ellipsoid: reference ellipsoid
    Outputs: easting (UTM easting), northing (UTM northing), zone (UTM zone number), hemisphere (N or S), k (point scale factor), gamma (grid convergence (degrees))
    See also: help("geo_utm_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_utm_forward", **given)

def geo_utm_inverse(easting=None, northing=None, zone=None, hemisphere=None, ellipsoid=None):
    """UTM coordinates to latitude and longitude. Latitude and longitude on the WGS84 or GRS80 ellipsoid of a point given by its UTM easting, northing, zone and hemisphere.
    Formula: \\xi' = \\xi - \\sum_{j=1}^{6}\\beta_j\\sin2j\\xi\\cosh2j\\eta,\\quad \\eta' = \\eta - \\sum_{j=1}^{6}\\beta_j\\cos2j\\xi\\sinh2j\\eta
    Inputs:
        easting: UTM easting
        northing: UTM northing
        zone: UTM zone number
        hemisphere: hemisphere of the zone (N: false northing 0; S: false northing 10000 km)
        ellipsoid: reference ellipsoid
    Outputs: lat (latitude (degrees)), lon (longitude (degrees))
    See also: help("geo_utm_inverse")
    """
    given = {k: v for k, v in dict(easting=easting, northing=northing, zone=zone, hemisphere=hemisphere, ellipsoid=ellipsoid).items() if v is not None}
    return _P.solve("geo_utm_inverse", **given)

def geo_utm_zone(lat=None, lon=None):
    """UTM zone, latitude band and central meridian. The Universal Transverse Mercator zone number (with the Norway and Svalbard exceptions), the MGRS latitude band letter, the hemisphere and the zone's central meridian for a latitude and longitude.
    Formula: z = \\left\\lfloor\\frac{\\lambda + 180^\\circ}{6^\\circ}\\right\\rfloor + 1,\\quad \\lambda_0 = 6z - 183^\\circ
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
    Outputs: zone (UTM zone number (1-60)), band (latitude band letter (C-X)), hemisphere (N or S), central_meridian (central meridian of the zone (degrees))
    See also: help("geo_utm_zone")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon).items() if v is not None}
    return _P.solve("geo_utm_zone", **given)

def geo_variogram_model_fit(h=None, gamma=None, model=None):
    """Fit an exponential or Gaussian variogram model (nugget, partial sill, range). The nugget, partial sill, range and sill of an exponential or Gaussian variogram model fitted by ordinary least squares to an empirical semivariogram (lags and semivariances).
    Formula: \\gamma(h) = c_0 + c\\left(1 - e^{-3h/a}\\right)\\ \\text{or}\\ c_0 + c\\left(1 - e^{-(7h/4a)^2}\\right),\\quad \\min_{c_0, c, a}\\sum_k\\left(\\hat\\gamma_k - \\gamma(h_k)\\right)^2
    Inputs:
        h: lag distances
        gamma: semivariances at the lags
        model: variogram model (pykrige parameterization, practical range)
    Outputs: nugget (nugget c0), psill (partial sill c), range (practical range a), sill (sill c0 + c)
    See also: help("geo_variogram_model_fit")
    """
    given = {k: v for k, v in dict(h=h, gamma=gamma, model=model).items() if v is not None}
    return _P.solve("geo_variogram_model_fit", **given)

def geo_vegetation_indices(red=None, nir=None, blue=None, L=None):
    """Vegetation indices: NDVI, EVI, SAVI, OSAVI, MSAVI and EVI2 from band reflectances. The common spectral vegetation indices of a pixel from its red, near-infrared and blue surface reflectances, with a stated soil adjustment factor L for SAVI (EVI uses its standard coefficients G = 2.5, C1 = 6, C2 = 7.5, L = 1).
    Formula: NDVI = \\frac{\\rho_{N} - \\rho_R}{\\rho_N + \\rho_R},\\ EVI = 2.5\\frac{\\rho_N - \\rho_R}{\\rho_N + 6\\rho_R - 7.5\\rho_B + 1},\\ SAVI = (1+L)\\frac{\\rho_N - \\rho_R}{\\rho_N + \\rho_R + L}
    Inputs:
        red: red reflectance (0-1)
        nir: near-infrared reflectance (0-1)
        blue: blue reflectance (0-1)
        L: SAVI soil adjustment factor (0.5 is usual)
    Outputs: NDVI ((NIR - R)/(NIR + R)), EVI (2.5 (NIR - R)/(NIR + 6R - 7.5B + 1)), SAVI ((1 + L)(NIR - R)/(NIR + R + L)), OSAVI ((NIR - R)/(NIR + R + 0.16)), MSAVI ((2NIR + 1 - sqrt((2NIR + 1)^2 - 8(NIR - R)))/2), EVI2 (2.5 (NIR - R)/(NIR + 2.4R + 1))
    See also: help("geo_vegetation_indices")
    """
    given = {k: v for k, v in dict(red=red, nir=nir, blue=blue, L=L).items() if v is not None}
    return _P.solve("geo_vegetation_indices", **given)

def geo_water_burn_built_indices(green=None, nir=None, swir1=None, swir2=None):
    """Water, moisture, burn and built-up indices: NDWI, MNDWI, NDMI, NBR and NDBI. Normalized-difference indices for open water (NDWI, MNDWI), vegetation moisture (NDMI), burn severity (NBR) and built-up land (NDBI) from green, near-infrared and two shortwave-infrared reflectances.
    Formula: ND(a, b) = \\frac{\\rho_a - \\rho_b}{\\rho_a + \\rho_b}
    Inputs:
        green: green reflectance (0-1)
        nir: near-infrared reflectance (0-1)
        swir1: shortwave infrared 1 (about 1.6 um) reflectance
        swir2: shortwave infrared 2 (about 2.2 um) reflectance
    Outputs: NDWI ((G - NIR)/(G + NIR)), MNDWI ((G - SWIR1)/(G + SWIR1)), NDMI ((NIR - SWIR1)/(NIR + SWIR1)), NBR ((NIR - SWIR2)/(NIR + SWIR2)), NDBI ((SWIR1 - NIR)/(SWIR1 + NIR))
    See also: help("geo_water_burn_built_indices")
    """
    given = {k: v for k, v in dict(green=green, nir=nir, swir1=swir1, swir2=swir2).items() if v is not None}
    return _P.solve("geo_water_burn_built_indices", **given)

def geo_watershed_delineation(dem=None, cell_size=None, row=None, col=None):
    """Watershed (catchment) of an outlet cell on a small DEM. The cells that drain to a chosen outlet cell under D8 flow directions: their number, the catchment area and the catchment mask.
    Formula: W(o) = \\{c : c \\to \\cdots \\to o\\}
    Inputs:
        dem: elevations (row 0 to the north), at most 900 cells
        cell_size: cell size
        row: outlet row (from 0, north)
        col: outlet column (from 0, west)
    Outputs: cells (number of cells in the catchment (outlet included)), area (catchment area), mask (1 for cells in the catchment, 0 elsewhere (matrix))
    See also: help("geo_watershed_delineation")
    """
    given = {k: v for k, v in dict(dem=dem, cell_size=cell_size, row=row, col=col).items() if v is not None}
    return _P.solve("geo_watershed_delineation", **given)

def geo_web_map_tile(lat=None, lon=None, zoom=None):
    """Web-map tile (slippy map / XYZ) and quadkey containing a point. The x and y indices of the web-map (XYZ / slippy map) tile containing a WGS84 point at a zoom level, and the tile's quadkey.
    Formula: x_t = \\left\\lfloor 2^z\\,\\frac{\\lambda + 180^\\circ}{360^\\circ}\\right\\rfloor,\\quad y_t = \\left\\lfloor 2^z\\left(\\frac12 - \\frac{\\operatorname{arsinh}(\\tan\\varphi)}{2\\pi}\\right)\\right\\rfloor
    Inputs:
        lat: latitude (decimal degrees)
        lon: longitude (decimal degrees)
        zoom: zoom level (0-24)
    Outputs: tile_x (tile column (from 180 W)), tile_y (tile row (from the north edge)), quadkey (quadkey of the tile)
    See also: help("geo_web_map_tile")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon, zoom=zoom).items() if v is not None}
    return _P.solve("geo_web_map_tile", **given)

def geo_web_mercator_forward(lat=None, lon=None):
    """Latitude and longitude to Web Mercator (EPSG:3857). Web Mercator (pseudo-Mercator, EPSG:3857) x and y of a WGS84 latitude and longitude, as used by web maps.
    Formula: x = R\\lambda,\\quad y = R\\ln\\tan\\left(\\frac{\\pi}{4} + \\frac{\\varphi}{2}\\right),\\quad R = 6378137\\ \\mathrm{m}
    Inputs:
        lat: latitude (WGS84) (decimal degrees)
        lon: longitude (WGS84) (decimal degrees)
    Outputs: x (Web Mercator x), y (Web Mercator y)
    See also: help("geo_web_mercator_forward")
    """
    given = {k: v for k, v in dict(lat=lat, lon=lon).items() if v is not None}
    return _P.solve("geo_web_mercator_forward", **given)

def geo_web_mercator_inverse(x=None, y=None):
    """Web Mercator (EPSG:3857) to latitude and longitude. WGS84 latitude and longitude of a point given by its Web Mercator (pseudo-Mercator) x and y.
    Formula: \\varphi = \\arctan\\sinh\\frac{y}{R},\\quad \\lambda = \\frac{x}{R}
    Inputs:
        x: Web Mercator x
        y: Web Mercator y
    Outputs: lat (latitude (degrees)), lon (longitude (degrees))
    See also: help("geo_web_mercator_inverse")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("geo_web_mercator_inverse", **given)

def geo_weighted_mean_center(x=None, y=None, w=None):
    """Weighted mean centre and weighted standard distance. The weighted mean centre of a set of points (e.g. population-weighted centroid) and the weighted standard distance about it.
    Formula: \\bar x_w = \\frac{\\sum w_ix_i}{\\sum w_i},\\quad SD_w = \\sqrt{\\frac{\\sum w_i\\left[(x_i - \\bar x_w)^2 + (y_i - \\bar y_w)^2\\right]}{\\sum w_i}}
    Inputs:
        x: x coordinates
        y: y coordinates
        w: non-negative weights
    Outputs: wmean_x (x of the weighted mean centre), wmean_y (y of the weighted mean centre), weighted_std_distance (weighted standard distance)
    See also: help("geo_weighted_mean_center")
    """
    given = {k: v for k, v in dict(x=x, y=y, w=w).items() if v is not None}
    return _P.solve("geo_weighted_mean_center", **given)


